UPDATE sys_chat_message
SET is_read = 1, read_time = #{readTime}
WHERE session_id = #{sessionId}
  AND receiver_id = #{receiverId}
  AND is_read = 0

UPDATE sys_chat_message SET is_read = 1, read_time = #{readTime}
WHERE session_id = #{sessionId} AND sender_id = #{userId}
  AND message_id <= #{throughMessageId} AND is_read = 0
